            and self.previous_closes.get("SPY") is not None
            and self.previous_closes["SPY"] <= self.previous_spy_sma_200
            and spy_bar.Close > current_spy_sma_200
        ):
            quantity = floor((0.40 * self.Portfolio.TotalPortfolioValue) / spy_bar.Close)
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
