                and self.previous_spy_close <= self.previous_spy_sma_200
                and spy_close > float(self.spy_sma_200.Current.Value)
            )

            if buy_a:
                target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                shares = int(target_value / spy_close)

                if shares > 0:
                    self.MarketOrder(self.spy, shares)
                    self.strategy_a_lot = shares

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20000:
                shares = int(20000 / aapl_close)

                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.strategy_b_lot = shares

        self._save_indicator_state()

    def _save_indicator_state(self):
        if self.spy_sma_200.IsReady:
            self.previous_spy_sma_200 = float(self.spy_sma_200.Current.Value)

        if self.spy_sma_50.IsReady:
            self.previous_spy_sma_50 = float(self.spy_sma_50.Current.Value)

        if self.spy in self.Securities and self.Securities[self.spy].HasData:
            self.previous_spy_close = float(self.Securities[self.spy].Close)
